package com.minewaku.chatter.identityaccess.user.internal.model;
import java.util.*;
public final class PasswordHash { private final String algorithm,hash; private final byte[] salt; public PasswordHash(String algorithm,String hash,byte[] salt){if(algorithm==null||algorithm.isBlank()||hash==null||hash.isBlank()||salt==null||salt.length==0)throw new IllegalArgumentException("Password hash requires algorithm, hash, and salt");this.algorithm=algorithm;this.hash=hash;this.salt=Arrays.copyOf(salt,salt.length);} public String algorithm(){return algorithm;} public String hash(){return hash;} public byte[] salt(){return Arrays.copyOf(salt,salt.length);}@Override public boolean equals(Object o){return o instanceof PasswordHash p&&algorithm.equals(p.algorithm)&&hash.equals(p.hash)&&Arrays.equals(salt,p.salt);}@Override public int hashCode(){return Objects.hash(algorithm,hash,Arrays.hashCode(salt));} }